		if branchName == defaultBranch {
			return nil
		}
		headCommit, err := repo.CommitObject(ref.Hash())
		if err != nil {
			return nil //nolint:nilerr // skip unreadable branch, keep indexing others
		}

		var stopAt *plumbing.Hash
		if defaultCommit != nil {
			if bases, err := headCommit.MergeBase(defaultCommit); err == nil && len(bases) > 0 {
				h := bases[0].Hash
				stopAt = &h
			}
		}
		indexBranchCheckpoints(headCommit, stopAt, branchName, index)
		return nil
	})
	if forEachErr != nil {
		return index
	}

	return index
}

// indexBranchCheckpoints walks branch-only history from start (stopping at
// stopAt, exclusive) and records each checkpoint trailer it finds under branch.
func indexBranchCheckpoints(start *object.Commit, stopAt *plumbing.Hash, branch string, index map[string]string) {
	const maxCommits = 100
	current := start
	for i := 0; current != nil && i < maxCommits; i++ {
		if stopAt != nil && current.Hash == *stopAt {
			return
		}
		for _, cpID := range trailers.ParseAllCheckpoints(current.Message) {
			key := cpID.String()
			if _, ok := index[key]; !ok {
				index[key] = branch
			}
		}
		if current.NumParents() == 0 {
			return
		}
		parent, err := current.Parent(0)
		if err != nil {
			return
		}
		current = parent
	}
}

