func ptrTime(t time.Time) *time.Time { return &t }

func TestFilterStoppedSessions(t *testing.T) {
	t.Parallel()

	base := time.Date(2026, 6, 1, 12, 0, 0, 0, time.UTC)
	active := &strategy.SessionState{SessionID: "active", Phase: session.PhaseActive, StartedAt: base}
	idle := &strategy.SessionState{SessionID: "idle", Phase: session.PhaseIdle, StartedAt: base}
	endedByPhase := &strategy.SessionState{SessionID: "ended-phase", Phase: session.PhaseEnded, StartedAt: base, EndedAt: ptrTime(base.Add(1 * time.Hour))}
	endedByTime := &strategy.SessionState{SessionID: "ended-time", Phase: session.PhaseIdle, StartedAt: base, EndedAt: ptrTime(base.Add(3 * time.Hour))}

	got := filterStoppedSessions([]*strategy.SessionState{nil, active, idle, endedByPhase, endedByTime})

	if len(got) != 2 {
		t.Fatalf("expected 2 stopped sessions, got %d", len(got))
	}
	// Sorted newest-stopped first: endedByTime (t+3h) before endedByPhase (t+1h).
	if got[0].SessionID != "ended-time" || got[1].SessionID != "ended-phase" {
		t.Fatalf("unexpected order: %s, %s", got[0].SessionID, got[1].SessionID)
	}
}

func TestSessionStoppedTime(t *testing.T) {
