// filterStoppedSessions returns sessions that have been stopped (explicitly
// ended), sorted newest-stopped first.
func filterStoppedSessions(states []*strategy.SessionState) []*strategy.SessionState {
	var stopped []*strategy.SessionState
	for _, s := range states {
		if s == nil {
			continue
		}
		if s.Phase == session.PhaseEnded || s.EndedAt != nil {
			stopped = append(stopped, s)
		}
	}
	sort.SliceStable(stopped, func(i, j int) bool {
		return sessionStoppedTime(stopped[i]).After(sessionStoppedTime(stopped[j]))
	})
	return stopped
}

// sessionStoppedTime returns the best timestamp to represent when a session was
// last touched: its end time, else last interaction, else start time.
func sessionStoppedTime(s *strategy.SessionState) time.Time {
	if s.EndedAt != nil {
		return *s.EndedAt
	}
	if s.LastInteractionTime != nil {
		return *s.LastInteractionTime
	}
	return s.StartedAt
}

